export const toggleFavoriteItem = async (studentId: string, itemId: string): Promise<void> => {
    let favorites = JSON.parse(localStorage.getItem('app_favorites') || '[]');
    const exists = favorites.find((f: any) => f.studentId === studentId && f.itemId === itemId);
    if (exists) {
        favorites = favorites.filter((f: any) => !(f.studentId === studentId && f.itemId === itemId));
    } else {
        favorites.push({ studentId, itemId });
    }
    localStorage.setItem('app_favorites', JSON.stringify(favorites));
    const { data: item } = await supabase.from('menu_items').select('favorite_count').eq('id', itemId).single();
    if (item) {
        const newCount = exists ? Math.max(0, item.favorite_count - 1) : item.favorite_count + 1;
        await supabase.from('menu_items').update({ favorite_count: newCount }).eq('id', itemId);
    }
};

