export const verifyQrCodeAndCollectOrder = async (qrToken: string, staffId: string): Promise<Order> => {
    let { data: orderData, error: findError } = await supabase.from('orders').select('*').eq('qr_token', qrToken).single();
    if (findError || !orderData) {
         const res = await supabase.from('orders').select('*').eq('id', qrToken).single();
         orderData = res.data;
         findError = res.error;
    }
    if (findError || !orderData) throw new Error("Invalid QR Code");
    if (orderData.status === 'collected') throw new Error("Order already collected.");
    if (orderData.status === 'cancelled') throw new Error("Order was cancelled.");

    const { data: staffData } = await supabase.from('users').select('username').eq('id', staffId).single();
    const staffName = staffData?.username || 'Staff Member';

    // Synchronize status to 'collected' to match RLS 'Delivered' rule
    const { data: updated, error: upError } = await supabase.from('orders')
        .update({ 
            status: 'collected', 
            delivered_by_staff_id: staffId, 
            delivered_by_staff_name: staffName,
            delivered_at: new Date().toISOString() 
        })
        .eq('id', orderData.id)
        .select()
        .single();

    if (upError) throw new Error(upError.message);
    return mapOrder(updated);
};

