export const redeemReward = async (studentId: string, rewardId: string): Promise<Offer> => {
    const { data: reward } = await supabase.from('rewards').select('*').eq('id', rewardId).single();
    if (!reward) throw new Error("Reward not found");
    const { data: user } = await supabase.from('users').select('loyalty_points').eq('id', studentId).single();
    if (!user || (user.loyalty_points || 0) < reward.points_cost) throw new Error("Not enough points");
    await supabase.from('users').update({ loyalty_points: (user.loyalty_points || 0) - reward.points_cost }).eq('id', studentId);
    const { data: offer, error } = await supabase.from('offers').insert([{
        code: `${reward.title.substring(0,3).toUpperCase()}${Date.now().toString().slice(-4)}`,
        description: `Reward: ${reward.title}`,
        discount_type: reward.discount_type,
        discount_value: reward.discount_value,
        is_reward: true,
        student_id: studentId,
        usage_count: 1
    }]).select().single();
    if (error) throw new Error(error.message);
    return mapOffer(offer);
};

export const submitFeedback = async (feedbackData: any): Promise<Feedback> => {
    const { data, error } = await supabase.from('feedbacks').insert([{
        student_id: feedbackData.studentId,
        student_name: feedbackData.studentName || 'Student',
        item_id: feedbackData.itemId,
        item_name: feedbackData.itemName || 'Item',
        rating: feedbackData.rating,
        comment: feedbackData.comment
    }]).select().single();

    if (error) throw new Error(error.message);

    try {
        const { data: allRatings } = await supabase
            .from('feedbacks')
            .select('rating')
            .eq('item_id', feedbackData.itemId);

        if (allRatings && allRatings.length > 0) {
            const sum = allRatings.reduce((acc, curr) => acc + curr.rating, 0);
            const avg = sum / allRatings.length;
            await supabase
                .from('menu_items')
                .update({ average_rating: avg })
                .eq('id', feedbackData.itemId);
        }
    } catch (e) {
        console.warn("Failed to sync average rating", e);
    }

    return mapFeedback(data);
};

