export const getTodaysDashboardStats = async (): Promise<TodaysDashboardStats> => {
    const today = new Date().toISOString().split('T')[0];
    const { data: orders } = await supabase.from('orders').select('*')
        .eq('payment_success', true)
        .gte('created_at', `${today}T00:00:00Z`)
        .neq('status', 'cancelled');
    if (!orders) return { totalOrders: 0, totalIncome: 0, itemsSold: [] };
    const totalIncome = orders.reduce((sum, o) => sum + Number(o.total_amount), 0);
    const itemCounts: Record<string, number> = {};
    orders.forEach(order => {
        const items = typeof order.items === 'string' ? JSON.parse(order.items) : order.items;
        items.forEach((item: any) => {
            itemCounts[item.name] = (itemCounts[item.name] || 0) + item.quantity;
        });
    });
    const itemsSold = Object.entries(itemCounts).map(([name, quantity]) => ({ name, quantity }));
    return { totalOrders: orders.length, totalIncome, itemsSold };
};

export const getMostSellingItems = async (): Promise<{ name: string; count: number }[]> => {
    const { data } = await supabase.from('orders').select('items').eq('payment_success', true);
    const counts: Record<string, number> = {};
    data?.forEach(o => {
        const items = typeof o.items === 'string' ? JSON.parse(o.items) : o.items;
        items.forEach((i: any) => counts[i.name] = (counts[i.name] || 0) + i.quantity);
    });
    return Object.entries(counts).map(([name, count]) => ({ name, count })).sort((a,b) => b.count - a.count).slice(0, 10);
};

