const OrderStatusBadge: React.FC<{ status: OrderStatus }> = ({ status }) => {
    const styles = {
        [OrderStatus.PENDING]: 'bg-yellow-500/20 text-yellow-300 border-yellow-500/50',
        [OrderStatus.PREPARED]: 'bg-blue-500/20 text-blue-300 border-blue-500/50',
        [OrderStatus.SEAT_SELECTED]: 'bg-purple-500/20 text-purple-300 border-purple-500/50',
        [OrderStatus.COLLECTED]: 'bg-green-500/20 text-green-300 border-green-500/50',
        [OrderStatus.CANCELLED]: 'bg-red-500/20 text-red-300 border-red-500/50',
    };
    return (
        <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase border tracking-wider ${styles[status] || 'bg-gray-500/20 text-gray-300 border-gray-500/50'}`}>
            {status}
        </span>
    );
};

const StaffActiveOrders: React.FC = () => {
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [isUpdating, setIsUpdating] = useState<string | null>(null);

    const fetchActive = useCallback(async () => {
        try {
            const data = await getStaffActiveOrders();
            setOrders(data);
        } catch (e) {
            console.error("Failed to fetch active orders", e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchActive();
        const interval = setInterval(fetchActive, 5000);
        return () => clearInterval(interval);
    }, [fetchActive]);

    const handleMarkDelivered = async (orderId: string) => {
        if (!window.confirm("Mark this order as DELIVERED to customer?")) return;
        setIsUpdating(orderId);
        try {
            // Synchronized with RLS: Staff can UPDATE status to 'collected'
            await updateOrderStatus(orderId, OrderStatus.COLLECTED);
            await fetchActive();
            window.dispatchEvent(new CustomEvent('show-owner-toast', { detail: { message: 'Order marked as Delivered.' } }));
        } catch (e) {
            window.dispatchEvent(new CustomEvent('show-owner-toast', { detail: { message: 'Action failed. Check permissions.' } }));
        } finally {
            setIsUpdating(null);
        }
    };

    if (loading && orders.length === 0) {
        return (
            <div className="mt-8 animate-pulse space-y-4">
                <div className="h-6 bg-white/5 rounded w-1/3"></div>
                <div className="h-24 bg-white/5 rounded-2xl"></div>
                <div className="h-24 bg-white/5 rounded-2xl"></div>
            </div>
        );
    }

    return (
        <div className="mt-10 w-full max-w-4xl mx-auto pb-10">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-black font-heading text-white flex items-center gap-2">
                    <span className="text-indigo-400">⚡</span> Live Active Orders
                </h2>
                <span className="bg-indigo-600/20 text-indigo-300 text-xs font-bold px-3 py-1 rounded-full border border-indigo-500/30">
                    {orders.length} ACTIVE
                </span>
            </div>

            {orders.length === 0 ? (
                <div className="bg-white/5 border border-white/10 rounded-2xl p-10 text-center">
                    <p className="text-gray-400 font-medium">No active orders needing preparation or pickup.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {orders.map(order => (
                        <div key={order.id} className="bg-gray-800/80 backdrop-blur-sm border border-white/10 p-5 rounded-2xl shadow-xl animate-fade-in-up">
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <div className="flex items-center gap-2 mb-1">
                                        <p className="font-black text-white text-lg">#{order.id.slice(-6)}</p>
                                        <OrderStatusBadge status={order.status} />
                                    </div>
                                    <p className="text-xs text-gray-400 font-bold uppercase tracking-tight">{order.studentName}</p>
                                </div>
                                {order.seatNumber && (
                                    <div className="bg-amber-500 text-black font-black px-3 py-1 rounded-lg text-sm shadow-lg shadow-amber-500/20">
                                        🪑 {order.seatNumber}
                                    </div>
                                )}
                            </div>

                            <div className="space-y-2 border-t border-white/5 pt-3 mb-4">
                                {order.items.map(item => (
                                    <div key={item.id} className="flex justify-between text-sm">
                                        <span className="text-gray-300 font-medium">{item.name} <span className="text-indigo-400 font-bold">x{item.quantity}</span></span>
                                        {item.notes && <span className="text-[10px] bg-indigo-500/10 text-indigo-300 px-2 py-0.5 rounded italic">Note: {item.notes}</span>}
                                    </div>
                                ))}
                            </div>

                            <div className="flex gap-2">
                                <button 
                                    onClick={() => handleMarkDelivered(order.id)}
                                    disabled={isUpdating === order.id}
                                    className="flex-grow bg-indigo-600 hover:bg-indigo-500 disabled:bg-indigo-800 text-white font-black py-3 rounded-xl text-sm transition-all transform active:scale-95 shadow-lg shadow-indigo-600/20"
                                >
                                    {isUpdating === order.id ? 'Processing...' : 'Mark as Delivered'}
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

