        id_proof_url: userData.idProofUrl,
        approval_status: userData.approval_status || 'approved'
    }]).select().single();
    if (error) {
        if (error.code === '23505') throw new Error('User with this phone or email already exists.');
        throw new Error(error.message);
    }
    return mapUser(data);
};

