    const handleDelete = async (itemId: string) => {
        if (!window.confirm("Are you sure you want to delete this menu item?")) {
            return;
        }

        try { 
            await removeMenuItem(itemId); 
            window.dispatchEvent(new CustomEvent('show-owner-toast', { detail: { message: 'Menu item deleted successfully' } }));
            setMenuItems(prevItems => prevItems.filter(item => item.id !== itemId));
        } 
        catch (error: any) { 
            console.error("Failed to delete menu item", error);
            const msg = error?.message || 'Failed to delete. Please try again.';
            window.dispatchEvent(new CustomEvent('show-owner-toast', { detail: { message: msg } }));
        }
    }

