export const getSalesByDate = async (dateStr: string) => {
    const startOfDay = `${dateStr}T00:00:00Z`;
    const endOfDay = `${dateStr}T23:59:59Z`;
    const { data, error } = await supabase.from('orders')
        .select('*')
        .eq('status', 'collected')
        .gte('delivered_at', startOfDay)
        .lte('delivered_at', endOfDay);
    if (error) return [];
    return data.map(mapOrder);
};

export const getTodaysDashboardStats = async (): Promise<TodaysDashboardStats> => {
    const today = new Date().toISOString().split('T')[0];
    const sales = await getSalesByDate(today);
    const totalIncome = sales.reduce((sum, o) => sum + o.totalAmount, 0);

    const itemsMap: Record<string, number> = {};
    sales.forEach(order => {
        order.items.forEach(item => {
            itemsMap[item.name] = (itemsMap[item.name] || 0) + item.quantity;
        });
    });

    const itemsSold = Object.entries(itemsMap).map(([name, quantity]) => ({ name, quantity }));
    return { totalOrders: sales.length, totalIncome, itemsSold };
};

export const getTodaysDetailedReport = async (): Promise<TodaysDetailedReport> => {
    const stats = await getTodaysDashboardStats();
    return {
        date: new Date().toISOString().split('T')[0],
        totalOrders: stats.totalOrders,
        totalIncome: stats.totalIncome,
        itemSales: stats.itemsSold.map(i => ({ name: i.name, quantity: i.quantity, totalPrice: 0 })) 
    };
};

