// --- API ERROR HELPER ---
const handleSupabaseError = (error: any, context: string) => {
    let message = error?.message;
    if (!message) {
        try {
            message = typeof error === 'object' ? JSON.stringify(error, null, 2) : String(error);
        } catch (e) {
            message = String(error);
        }
    }

    if (message.includes("violates row-level security policy")) {
        const tableName = context.split(' ').pop() || 'table';
        message = `Row-Level Security Violation on "${tableName}". Action Required: Run "ALTER TABLE ${tableName.toLowerCase()} DISABLE ROW LEVEL SECURITY;" in Supabase SQL Editor.`;
    }

    console.error(`[Supabase Error] ${context}:`, message);
    throw new Error(message);
};

