export const getTodaysDashboardStats = async (): Promise<TodaysDashboardStats> => {
    const today = new Date().toISOString().split('T')[0];
    const orders = await getSalesByDate(today);

    const itemMap: Record<string, number> = {};
    let totalIncome = 0;

    orders.forEach(order => {
        totalIncome += Number(order.totalAmount);
        order.items.forEach(item => {
            itemMap[item.name] = (itemMap[item.name] || 0) + item.quantity;
        });
    });

    const itemsSold = Object.entries(itemMap).map(([name, quantity]) => ({
        name,
        quantity
    })).sort((a, b) => b.quantity - a.quantity);

    return {
        totalOrders: orders.length,
        totalIncome,
        itemsSold
    };
};

export const getTodaysDetailedReport = async (): Promise<TodaysDetailedReport> => {
    const today = new Date().toISOString().split('T')[0];
    const stats = await getTodaysDashboardStats();

    // Detailed item report
    const orders = await getSalesByDate(today);
    const itemDetails: Record<string, { quantity: number; totalPrice: number }> = {};

    orders.forEach(order => {
        order.items.forEach(item => {
            if (!itemDetails[item.name]) {
                itemDetails[item.name] = { quantity: 0, totalPrice: 0 };
            }
            itemDetails[item.name].quantity += item.quantity;
            itemDetails[item.name].totalPrice += (item.price * item.quantity);
        });
    });

    const itemSales = Object.entries(itemDetails).map(([name, data]) => ({
        name,
        quantity: data.quantity,
        totalPrice: data.totalPrice
    }));

    return {
        date: today,
        totalOrders: stats.totalOrders,
        totalIncome: stats.totalIncome,
        itemSales
    };
};

