/**
 * Customer Order History Query
 * Rules: payment_status == "paid" AND order_status IN ("Confirmed", "Prepared", "Delivered")
 */
export const getStudentOrders = async (studentId: string): Promise<Order[]> => {
    const { data, error } = await supabase.from('orders')
        .select('*')
        .eq('student_id', studentId)
        .eq('payment_status', 'paid')
        .in('status', [OrderStatusEnum.CONFIRMED, OrderStatusEnum.PREPARED, OrderStatusEnum.DELIVERED, OrderStatusEnum.COLLECTED, OrderStatusEnum.PENDING])
        .order('created_at', { ascending: false });

    if (error) return [];
    return data.map(mapOrder);
};

export const getOrderById = async (orderId: string): Promise<Order | null> => {
    const { data, error } = await supabase.from('orders').select('*').eq('id', orderId).maybeSingle();
