export const verifyQrCodeAndCollectOrder = async (qrToken: string, staffId: string): Promise<Order> => {
    const { data, error } = await supabase.from('orders').select('*').eq('qr_token', qrToken).maybeSingle();
    if (error || !data) throw new Error("Invalid QR Code");
    if (data.status === OrderStatusEnum.DELIVERED || data.status === OrderStatusEnum.COLLECTED) throw new Error("Order already collected.");

    await updateOrderStatus(data.id, OrderStatusEnum.DELIVERED, staffId);
    return mapOrder({ ...data, status: OrderStatusEnum.DELIVERED });
};

