const StaffOrderList: React.FC = () => {
    const { user } = useAuth();
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [isUpdating, setIsUpdating] = useState<string | null>(null);

    const fetchActive = useCallback(async () => {
        try {
            const data = await getStaffActiveOrders();
            setOrders(data);
        } catch (e) {
            console.error("Failed to fetch staff orders", e);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchActive();
        const interval = setInterval(fetchActive, 5000);
        return () => clearInterval(interval);
    }, [fetchActive]);

    const handleMarkReady = async (orderId: string) => {
        if (!window.confirm("Mark this order as Prepared?")) return;
        setIsUpdating(orderId);
        try {
            await updateOrderStatus(orderId, OrderStatus.PREPARED);
            await fetchActive();
            window.dispatchEvent(new CustomEvent('show-owner-toast', { detail: { message: 'Order marked as Prepared!' } }));
        } catch (e) {
            window.dispatchEvent(new CustomEvent('show-owner-toast', { detail: { message: 'Update failed.' } }));
        } finally {
            setIsUpdating(null);
        }
    };

    if (loading && orders.length === 0) return <div className="p-10 text-center animate-pulse text-gray-500">Loading orders...</div>;

    return (
        <div className="space-y-4 max-w-2xl mx-auto w-full">
            <div className="flex justify-between items-center mb-2 px-2">
