                                ) : (
                                    <div className="w-full py-4 text-center border-2 border-dashed border-blue-500/30 rounded-xl">
                                        <p className="text-blue-400 font-bold text-sm">Waiting for QR Scan Delivery</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

