/**
 * Place Order - Defensive against missing columns
 */
export const placeOrder = async (order: any): Promise<Order> => {
    const payload: any = {
        student_id: order.studentId,
        student_name: order.studentName,
        customer_phone: order.customerPhone,
        items: order.items,
        total_amount: order.totalAmount,
        status: order.status || OrderStatusEnum.PENDING,
        payment_status: 'created',
        qr_token: `ORD-${Date.now()}-${Math.floor(Math.random()*1000)}`,
        seat_number: order.seat_number,
        payment_success: false
    };

    const { data, error } = await supabase.from('orders').insert([payload]).select().single();

    if (error) {
        // If column 'payment_status' is missing, retry without it
        if (error.message.includes('payment_status') || error.code === 'P0001' || error.code === '42703') {
            console.warn("DB Column 'payment_status' missing. Retrying without it.");
            delete payload.payment_status;
            const retry = await supabase.from('orders').insert([payload]).select().single();
            if (retry.error) handleSupabaseError(retry.error, "Orders Insert Retry Fallback");
            return mapOrder(retry.data);
        }
        handleSupabaseError(error, "Orders Insert");
    }
    return mapOrder(data);
};

export const updateOrderStatus = async (orderId: string, status: OrderStatusEnum, staffId?: string, staffName?: string): Promise<void> => {
    if ((status === OrderStatusEnum.COLLECTED || status === OrderStatusEnum.DELIVERED) && !staffId) {
         throw new Error("Delivery requires a QR scan by staff.");
    }

    const updates: any = { status };
    if (status === OrderStatusEnum.COLLECTED || status === OrderStatusEnum.DELIVERED) {
        updates.delivered_at = new Date().toISOString();
        if (staffId) updates.delivered_by_staff_id = staffId;
        if (staffName) updates.delivered_by_staff_name = staffName;
    }
    const { error } = await supabase.from('orders').update(updates).eq('id', orderId);
    if (error) handleSupabaseError(error, "Orders Status Update");
};

/**
 * Update Payment - Defensive against missing columns
 */
export const updateOrderPaymentStatus = async (orderId: string, success: boolean): Promise<void> => {
    const updates: any = { 
        payment_success: success,
        payment_status: success ? 'paid' : 'failed'
    };

    if (success) {
        updates.status = OrderStatusEnum.CONFIRMED;
    }

    const { error } = await supabase.from('orders').update(updates).eq('id', orderId);
    if (error) {
        if (error.message.includes('payment_status') || error.code === '42703') {
            delete updates.payment_status;
            const retry = await supabase.from('orders').update(updates).eq('id', orderId);
            if (retry.error) handleSupabaseError(retry.error, "Orders Payment Fallback");
        } else {
            handleSupabaseError(error, "Orders Payment Status Update");
        }
    }
};

