    return {
        id,
        name: userRow?.username || 'Customer',
        phone: userRow?.phone || 'N/A',
        totalOrders,
        lifetimeSpend,
        favoriteItemsCount: favCount || 0,
        loyaltyPoints: userRow?.loyalty_points || 0
    };
