// --- ANALYTICS (FIXED) ---

export const getTodaysDashboardStats = async (): Promise<TodaysDashboardStats> => {
    const startOfDay = new Date();
    startOfDay.setHours(0, 0, 0, 0);
    const endOfDay = new Date();
    endOfDay.setHours(23, 59, 59, 999);

    const { data, error } = await supabase
        .from('orders')
        .select('items, total_amount')
        .eq('payment_status', 'paid')
        .gte('created_at', startOfDay.toISOString())
        .lte('created_at', endOfDay.toISOString());

    if (error || !data) return { totalOrders: 0, totalIncome: 0, itemsSold: [] };

    const itemMap = new Map<string, number>();
    let totalIncome = 0;

    data.forEach(order => {
        totalIncome += Number(order.total_amount);
        const items = order.items ? (typeof order.items === 'string' ? JSON.parse(order.items) : order.items) : [];
        items.forEach((item: any) => {
            itemMap.set(item.name, (itemMap.get(item.name) || 0) + item.quantity);
        });
    });

    const itemsSold = Array.from(itemMap.entries()).map(([name, quantity]) => ({ name, quantity }));

    return {
        totalOrders: data.length,
        totalIncome,
        itemsSold
    };
};

export const getSalesSummary = async (): Promise<SalesSummary> => {
    const twentyEightDaysAgo = new Date();
    twentyEightDaysAgo.setDate(twentyEightDaysAgo.getDate() - 28);
    twentyEightDaysAgo.setHours(0, 0, 0, 0);

    const { data, error } = await supabase
        .from('orders')
        .select('created_at, total_amount')
        .eq('payment_status', 'paid')
        .gte('created_at', twentyEightDaysAgo.toISOString());

    if (error || !data) return { daily: [], weekly: [] };

    // Group Daily
    const dailyMap = new Map<string, number>();
    // Group Weekly (bucketing into 7-day windows)
    const weeklyBuckets = [0, 0, 0, 0]; // Last 4 weeks
    const today = new Date();

    data.forEach(order => {
        const d = new Date(order.created_at);
        const dateKey = d.toLocaleDateString('en-GB');
        dailyMap.set(dateKey, (dailyMap.get(dateKey) || 0) + Number(order.total_amount));

        const diffDays = Math.floor((today.getTime() - d.getTime()) / (1000 * 3600 * 24));
        const weekIdx = Math.floor(diffDays / 7);
        if (weekIdx >= 0 && weekIdx < 4) {
            weeklyBuckets[weekIdx] += Number(order.total_amount);
        }
    });

    const daily = Array.from(dailyMap.entries()).map(([date, total]) => ({ date, total }));
    const weekly = weeklyBuckets.reverse().map((total, i) => ({ 
        week: i === 3 ? 'This Week' : `Week -${3-i}`, 
        total 
    }));

    return { daily, weekly };
};

export const getMostSellingItems = async () => {
    const { data } = await supabase.from('orders').select('items').eq('payment_status', 'paid');
    if (!data) return [];
    const map = new Map<string, number>();
    data.forEach(o => {
        const items = o.items ? (typeof o.items === 'string' ? JSON.parse(o.items) : o.items) : [];
        items.forEach((i: any) => map.set(i.name, (map.get(i.name) || 0) + i.quantity));
    });
    return Array.from(map.entries()).map(([name, count]) => ({ name, count })).sort((a,b) => b.count - a.count).slice(0, 5);
