    await updateOrderStatus(order.id, OrderStatusEnum.COLLECTED, staffId, staff?.username);
    return { ...order, status: OrderStatusEnum.COLLECTED, deliveredByStaffId: staffId, deliveredByStaffName: staff?.username };
};
