export const getTodaysDashboardStats = async (): Promise<TodaysDashboardStats> => {
    const today = new Date();
    today.setHours(0,0,0,0);

    const { data, error } = await supabase
        .from('orders')
        .select('items, total_amount')
        .eq('payment_status', 'paid')
        .gte('created_at', today.toISOString());

    if (error || !data) return { totalOrders: 0, totalIncome: 0, itemsSold: [] };

    const itemAggregates = new Map<string, number>();
    let income = 0;

    data.forEach(order => {
        income += Number(order.total_amount);
        const items = Array.isArray(order.items) ? order.items : (typeof order.items === 'string' ? JSON.parse(order.items) : []);
        items.forEach((item: any) => {
            itemAggregates.set(item.name, (itemAggregates.get(item.name) || 0) + item.quantity);
        });
    });

    return {
        totalOrders: data.length,
        totalIncome: income,
        itemsSold: Array.from(itemAggregates.entries()).map(([name, quantity]) => ({ name, quantity }))
    };
};

export const getSalesSummary = async (): Promise<SalesSummary> => {
    // Generate last 14 days
    const daily: { date: string; total: number }[] = [];
    const today = new Date();

    for (let i = 13; i >= 0; i--) {
        const d = new Date();
        d.setDate(today.getDate() - i);
        daily.push({ date: d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short' }), total: 0 });
    }

    const fourteenDaysAgo = new Date();
    fourteenDaysAgo.setDate(today.getDate() - 14);
    fourteenDaysAgo.setHours(0,0,0,0);

    const { data, error } = await supabase
        .from('orders')
        .select('created_at, total_amount')
        .eq('payment_status', 'paid')
        .gte('created_at', fourteenDaysAgo.toISOString());

    if (data) {
        data.forEach(order => {
            const orderDate = new Date(order.created_at).toLocaleDateString('en-GB', { day: '2-digit', month: 'short' });
            const dayBucket = daily.find(d => d.date === orderDate);
            if (dayBucket) {
                dayBucket.total += Number(order.total_amount);
            }
        });
    }

    // Weekly summary (still kept for data consistency in context, though UI shows daily)
    const weeklyBuckets = [0, 0, 0, 0];
    if (data) {
        data.forEach(order => {
            const diffDays = Math.floor((today.getTime() - new Date(order.created_at).getTime()) / (1000 * 3600 * 24));
            const weekIdx = Math.floor(diffDays / 7);
            if (weekIdx >= 0 && weekIdx < 4) weeklyBuckets[weekIdx] += Number(order.total_amount);
        });
    }

    return {
        daily,
        weekly: weeklyBuckets.reverse().map((total, i) => ({ 
            week: i === 3 ? 'This Week' : `Week -${3-i}`, 
            total 
        }))
    };
};

