    const activeOrders = useMemo(() => 
        orders
            .filter(o => o.status === OrderStatus.PENDING || o.status === OrderStatus.PREPARED)
            .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()), 
