            } />
            <Route path="/admin/sales-report" element={
                 <ProtectedRoute allowedRoles={[Role.ADMIN]}>
                    <AdminSalesReportPage />
                </ProtectedRoute>
            } />

            <Route path="*" element={<NotFoundPage />} />
        </Routes>
    );
}


