    if (error || !orders) return [];

    const itemsMap = new Map<string, number>();
    orders.forEach(o => {
        const items = parseOrderItems(o.items);
        items.forEach((i: any) => {
            if (i.name) {
                itemsMap.set(i.name, (itemsMap.get(i.name) || 0) + (Number(i.quantity) || 1));
