/**
 * Creates a Razorpay Order.
 * Detects if the Edge Function is reachable. If not, returns { simulation: true }.
 */
export const createRazorpayOrderApi = async (amount: number, studentId: string) => {
    try {
        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount, studentId }
        });

        // Error from Supabase (e.g. 404 or request failed)
        if (error) {
            console.warn("Edge Function unreachable. Fallback to simulation mode.");
            return { simulation: true, amount: amount * 100, currency: 'INR' };
        }

        // Logic error inside the function (e.g. key missing)
        if (data?.error) {
            console.warn("Function returned logic error. Fallback to simulation mode.");
            return { simulation: true, amount: amount * 100, currency: 'INR' };
        }

        return data;
    } catch (err) {
        // Network/DNS error
        console.warn("Network error reaching payment server. Fallback to simulation mode.");
        return { simulation: true, amount: amount * 100, currency: 'INR' };
    }
};

/**
 * Verifies a Razorpay Payment.
 */
export const verifyRazorpayPaymentApi = async (orderId: string, razorpayResponse: any) => {
    // If it's a simulated order (no real signature from Razorpay SDK), bypass
    if (!razorpayResponse.razorpay_signature) {
        return true;
    }

    try {
        const { data, error } = await supabase.functions.invoke('verify-razorpay-payment', {
            body: { 
                orderId, 
                razorpay_order_id: razorpayResponse.razorpay_order_id,
                razorpay_payment_id: razorpayResponse.razorpay_payment_id,
                razorpay_signature: razorpayResponse.razorpay_signature
            }
        });

        if (error) return true; // Accept for demo if verification server is technically down
        return data?.success ?? true;
    } catch (err) {
        return true; 
    }
};

