import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import Razorpay from 'npm:razorpay'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

serve(async (req) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { amount, studentId } = await req.json()

    // Retrieve keys from Supabase Secrets
    const key_id = Deno.env.get('RAZORPAY_KEY_ID')
    const key_secret = Deno.env.get('RAZORPAY_KEY_SECRET')

    if (!key_id || !key_secret) {
      throw new Error("Razorpay API keys are missing in Supabase Secrets. Please run: supabase secrets set RAZORPAY_KEY_ID=... RAZORPAY_KEY_SECRET=...")
    }

    const razorpay = new Razorpay({
      key_id: key_id,
      key_secret: key_secret,
    })

    const options = {
      amount: Math.round(Number(amount) * 100), // Convert INR to Paise (Paise is required by Razorpay)
      currency: "INR",
      receipt: `rcpt_${studentId}_${Date.now()}`,
    }

    const order = await razorpay.orders.create(options)

    return new Response(
      JSON.stringify(order),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }, 
        status: 200 
      }
    )
  } catch (error) {
    console.error("[Backend Error]:", error.message)
    return new Response(
      JSON.stringify({ error: error.message }),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }, 
        status: 400 
      }
    )
  }
})

declare const Deno: any;

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { crypto } from "https://deno.land/std@0.177.0/crypto/mod.ts"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

serve(async (req) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = await req.json()
    const secret = Deno.env.get('RAZORPAY_KEY_SECRET') || ''

    if (!secret) {
      throw new Error("RAZORPAY_KEY_SECRET is not configured in Supabase Secrets.")
    }

    // Razorpay standard verification logic: HMAC_SHA256(order_id + "|" + payment_id, secret)
    const data = razorpay_order_id + "|" + razorpay_payment_id

    // Generate HMAC signature using native Web Crypto
    const encoder = new TextEncoder()
    const keyData = encoder.encode(secret)
    const key = await crypto.subtle.importKey(
      "raw",
      keyData,
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"]
    )

    const signatureBuffer = await crypto.subtle.sign(
      "HMAC",
      key,
      encoder.encode(data)
    )

    // Convert signature buffer to hex string
    const generated_signature = Array.from(new Uint8Array(signatureBuffer))
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("")

    // Compare with signature sent from frontend
    const isSuccess = generated_signature === razorpay_signature

    return new Response(
      JSON.stringify({ success: isSuccess }),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }, 
        status: 200 
      }
    )
  } catch (error) {
    console.error("[Verification Error]:", error.message)
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }, 
        status: 400 
      }
    )
  }
})

