import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import Razorpay from 'npm:razorpay'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

serve(async (req) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { amount, studentId } = await req.json()

    // Use Deno.env for Supabase Secrets
    const key_id = Deno.env.get('RAZORPAY_KEY_ID')
    const key_secret = Deno.env.get('RAZORPAY_KEY_SECRET')

    if (!key_id || !key_secret) {
      throw new Error("Razorpay API keys are missing in Supabase Secrets.")
    }

    const razorpay = new Razorpay({
      key_id: key_id,
      key_secret: key_secret,
    })

    const options = {
      amount: Math.round(Number(amount) * 100), // Convert INR to Paise
      currency: "INR",
      receipt: `rcpt_${studentId}_${Date.now()}`,
    }

    const order = await razorpay.orders.create(options)

    return new Response(
      JSON.stringify(order),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }, 
        status: 200 
      }
    )
  } catch (error: any) {
    console.error("[Razorpay Error]:", error.message)
    return new Response(
      JSON.stringify({ error: error.message }),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }, 
        status: 400 
      }
    )
  }
})

