    try {
        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount, studentId }
        });

        // If there's a function error or data is missing, trigger simulation
        if (error || !data || data.error) {
            console.warn("Edge Function failed or returned error. Triggering Simulation Fallback.", error || data?.error);
            return { simulation: true, amount: amount * 100, currency: 'INR' };
        }
        return data;
    } catch (err) {
        console.warn("Catch block triggered. Function connection failed. Switching to Simulation Mode.", err);
        return { simulation: true, amount: amount * 100, currency: 'INR' };
    }
};

