// --- RAZORPAY EDGE FUNCTION INTEGRATION ---

/**
 * Creates a Razorpay order via Supabase Edge Functions.
 * Falls back to simulation mode if the network is unreachable or the function fails.
 */
export const createRazorpayOrderApi = async (amount: number, studentId: string) => {
    const cleanAmount = Number(amount);
    try {
        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount: cleanAmount, studentId }
        });

        // Handle explicit function errors
        if (error || !data || data.error) {
            console.warn("Edge Function reported an error. Activating Simulation Fallback.", error || data?.error);
            return { simulation: true, amount: cleanAmount * 100, currency: 'INR' };
        }

        return data;
    } catch (err) {
        // This block catches "Failed to fetch" (Network/CORS/DNS errors)
        console.error("Critical Network Error reaching Edge Function:", err);
        return { 
            simulation: true, 
            amount: cleanAmount * 100, 
            currency: 'INR', 
            reason: 'network_failure' 
        };
    }
};

export const verifyRazorpayPaymentApi = async (orderId: string, razorpayResponse: any) => {
    // Skip verification for simulated payments
    if (!razorpayResponse || !razorpayResponse.razorpay_signature) {
        return true;
    }

    try {
        const { data, error } = await supabase.functions.invoke('verify-razorpay-payment', {
            body: { 
                razorpay_order_id: razorpayResponse.razorpay_order_id,
                razorpay_payment_id: razorpayResponse.razorpay_payment_id,
                razorpay_signature: razorpayResponse.razorpay_signature
            }
        });
        if (error) {
            console.warn("Verification function unreachable. Assuming manual check needed, allowing through for demo.");
            return true;
        }
        return data?.success ?? true;
    } catch (err) {
        console.error("Verification network error:", err);
        return true; 
    }
};

