export const createRazorpayOrderApi = async (amount: number, studentId: string) => {
    const cleanAmount = Number(amount);
    try {
        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount: cleanAmount, studentId }
        });

        if (error) {
            console.error("Invoke Error Details:", error);
            return { simulation: true, amount: cleanAmount * 100, currency: 'INR' };
        }

        if (!data || data.error) {
            console.warn("Function Logic Error:", data?.error || "Empty Response");
            return { simulation: true, amount: cleanAmount * 100, currency: 'INR' };
        }

        return data;
    } catch (err) {
        console.error("Browser Network Error (CORS/Blocked):", err);
        return { 
            simulation: true, 
            amount: cleanAmount * 100, 
            currency: 'INR', 
            reason: 'network_failure' 
        };
    }
};

