import "https://deno.land/x/xhr@0.1.0/mod.ts"
import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import Razorpay from 'npm:razorpay'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Max-Age': '86400',
}

serve(async (req) => {
  console.log(`Request received: ${req.method}`)

  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { amount, studentId } = await req.json()
    console.log(`Creating order for Student: ${studentId}, Amount: ${amount}`)

    // Fix: Replaced Deno.env.get with process.env to avoid 'Cannot find name Deno' error
    const key_id = (process.env as any).RAZORPAY_KEY_ID
    const key_secret = (process.env as any).RAZORPAY_KEY_SECRET

    if (!key_id || !key_secret) {
      console.error("CRITICAL ERROR: Razorpay keys are missing in Supabase Secrets!")
      throw new Error("Razorpay keys missing in Supabase Dashboard.")
    }

    const razorpay = new Razorpay({
      key_id: key_id,
      key_secret: key_secret,
    })

    const options = {
      amount: Math.round(Number(amount) * 100), // INR to Paise
      currency: "INR",
      receipt: `rcpt_${studentId}_${Date.now()}`,
    }

    const order = await razorpay.orders.create(options)
    console.log(`Razorpay Order Created: ${order.id}`)

    return new Response(
      JSON.stringify(order),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
    )
  } catch (error: any) {
    console.error("Function Error:", error.message)
    return new Response(
      JSON.stringify({ error: error.message }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
    )
  }
})

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { crypto } from "https://deno.land/std@0.177.0/crypto/mod.ts"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = await req.json()
    // Fix: Replaced Deno.env.get with process.env to avoid 'Cannot find name Deno' error
    const secret = (process.env as any).RAZORPAY_KEY_SECRET

    if (!secret) throw new Error("RAZORPAY_KEY_SECRET is not configured.")

    const data = razorpay_order_id + "|" + razorpay_payment_id
    const encoder = new TextEncoder()
    const keyData = encoder.encode(secret)
    const key = await crypto.subtle.importKey(
      "raw", keyData, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]
    )

    const signatureBuffer = await crypto.subtle.sign("HMAC", key, encoder.encode(data))
    const generated_signature = Array.from(new Uint8Array(signatureBuffer))
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("")

    const isSuccess = generated_signature === razorpay_signature
    console.log(`Payment Verification: ${isSuccess ? 'SUCCESS' : 'FAILED'}`)

    return new Response(
      JSON.stringify({ success: isSuccess }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
    )
  } catch (error: any) {
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
    )
  }
})

