};

// --- RAZORPAY EDGE FUNCTION INTEGRATION ---

export const createRazorpayOrderApi = async (amount: number, studentId: string) => {
    const cleanAmount = Number(amount);
    try {
        console.log(`Invoking Edge Function at ${SUPABASE_URL}/functions/v1/create-razorpay-order`);
        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount: cleanAmount, studentId }
        });

        if (error) {
            console.error("Invoke error details:", error);
            // If the error contains context about deployment, we give a better UI message
            throw new Error(`Connection to Payment Server failed. Check if the function is deployed at ${SUPABASE_URL}.`);
        }

        if (!data || data.error) {
            throw new Error(data?.error || "The payment server returned an error.");
        }

        return data;
    } catch (err: any) {
        console.error("createRazorpayOrderApi Exception:", err);
        // Ensure we throw a real error object for the Toast to handle
        if (err instanceof Error) throw err;
        throw new Error(String(err));
    }
};

export const verifyRazorpayPaymentApi = async (orderId: string, razorpayResponse: any) => {
    if (!razorpayResponse || !razorpayResponse.razorpay_signature) {
        return false; 
    }

    try {
        const { data, error } = await supabase.functions.invoke('verify-razorpay-payment', {
            body: { 
                razorpay_order_id: razorpayResponse.razorpay_order_id,
                razorpay_payment_id: razorpayResponse.razorpay_payment_id,
                razorpay_signature: razorpayResponse.razorpay_signature
            }
        });
        if (error) return false;
        return data?.success ?? false;
    } catch (err) {
        return false; 
    }
};

