const KEY_ID = Deno.env.get('RAZORPAY_KEY_ID') || 'rzp_live_S0V6Bz1xXIWsbn';
const KEY_SECRET = Deno.env.get('RAZORPAY_KEY_SECRET') || 'aleVqiBaaVo8ZatFBmWQS1vV';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Max-Age': '86400',
}

Deno.serve(async (req) => {
  // Handle CORS Preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { amount, studentId } = await req.json()
    console.log(`Processing Order: Student ${studentId}, Amount ${amount}`)

    if (!amount) {
      throw new Error("Amount is required")
    }

    // Call Razorpay API using Basic Auth
    // Deno has built-in btoa and fetch support
    const auth = btoa(`${KEY_ID}:${KEY_SECRET}`)
    const razorpayResponse = await fetch('https://api.razorpay.com/v1/orders', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Basic ${auth}`
      },
      body: JSON.stringify({
        amount: Math.round(Number(amount) * 100), // Convert INR to Paise
        currency: "INR",
        receipt: `rcpt_${studentId}_${Date.now()}`,
      })
    })

    const orderData = await razorpayResponse.json()

    if (!razorpayResponse.ok) {
      console.error("Razorpay API Error:", orderData)
      return new Response(
        JSON.stringify({ error: orderData.error?.description || "Razorpay API Error" }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
      )
    }

    return new Response(
      JSON.stringify(orderData),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
    )

  } catch (error: any) {
    console.error("Edge Function Runtime Error:", error.message)
    return new Response(
      JSON.stringify({ error: error.message }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
    )
  }
})

import { crypto } from "https://deno.land/std@0.177.0/crypto/mod.ts"

const KEY_SECRET = Deno.env.get('RAZORPAY_KEY_SECRET') || 'aleVqiBaaVo8ZatFBmWQS1vV';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Max-Age': '86400',
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = await req.json()

    const data = razorpay_order_id + "|" + razorpay_payment_id
    const encoder = new TextEncoder()
    const keyData = encoder.encode(KEY_SECRET)
    const key = await crypto.subtle.importKey(
      "raw", keyData, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]
    )

    const signatureBuffer = await crypto.subtle.sign("HMAC", key, encoder.encode(data))
    const generated_signature = Array.from(new Uint8Array(signatureBuffer))
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("")

    const isSuccess = generated_signature === razorpay_signature

    return new Response(
      JSON.stringify({ success: isSuccess }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
    )
  } catch (error: any) {
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
    )
  }
})

