const handleSupabaseError = (error: any, context: string) => {
    let message = error?.message || "Database Connection Error";
    console.error(`[Supabase Error] ${context}:`, message, error);
    throw new Error(message);
};

// --- RAZORPAY EDGE FUNCTION INTEGRATION ---

export const createRazorpayOrderApi = async (amount: number, studentId: string) => {
    const cleanAmount = Number(amount);
    try {
        console.log(`Invoking create-razorpay-order...`);
        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount: cleanAmount, studentId }
        });

        // If the Edge Function returns an error object
        if (error) {
            console.error("Supabase Invoke Error:", error);

            // "Failed to send a request" usually means the function is not deployed or CORS failed.
            // We return a simulation object so the app flow can continue for testers.
            if (error.message?.includes('Failed to send a request') || error.status === 404) {
                return { 
                    simulation: true, 
                    reason: "Edge Function not found or unreachable. Please run 'supabase functions deploy create-razorpay-order'.",
                    error_type: "connectivity"
                };
            }
            throw error;
        }

        // If function executed but returned its own error in data
        if (!data || data.error) {
            throw new Error(data?.error || "The payment server returned an empty or invalid response.");
        }

        return data;
    } catch (err: any) {
        console.error("createRazorpayOrderApi Catch:", err);
        // Fallback for unexpected failures to keep the UI active
        return { 
            simulation: true, 
            reason: err.message || "Unknown connectivity error.",
            error_type: "exception"
        };
    }
};

export const verifyRazorpayPaymentApi = async (orderId: string, razorpayResponse: any) => {
    if (!razorpayResponse || !razorpayResponse.razorpay_signature) {
        return false; 
    }

    try {
        const { data, error } = await supabase.functions.invoke('verify-razorpay-payment', {
            body: { 
                razorpay_order_id: razorpayResponse.razorpay_order_id,
                razorpay_payment_id: razorpayResponse.razorpay_payment_id,
                razorpay_signature: razorpayResponse.razorpay_signature
            }
        });
        if (error) {
            console.error("Verification Function Unreachable:", error);
            return false;
        }
        return data?.success ?? false;
    } catch (err) {
        console.error("Verification Exception:", err);
        return false; 
    }
};

