Deno.serve(async (req: Request) => {
  // 1. Handle CORS Preflight (CRITICAL for fixing "Failed to send request")
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { amount, studentId } = await req.json()
    console.log(`[OrderRequest] Student: ${studentId}, Amount: ${amount}`)

    // Configuration - Using user provided live keys as fallback
    const KEY_ID = Deno.env.get('RAZORPAY_KEY_ID') || 'rzp_live_S0V6Bz1xXIWsbn';
    const KEY_SECRET = Deno.env.get('RAZORPAY_KEY_SECRET') || 'aleVqiBaaVo8ZatFBmWQS1vV';

    if (!amount) {
      throw new Error("Missing amount parameter")
    }

    // 2. Call Razorpay API using Basic Auth
    const auth = btoa(`${KEY_ID}:${KEY_SECRET}`)
    const razorpayResponse = await fetch('https://api.razorpay.com/v1/orders', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Basic ${auth}`
      },
      body: JSON.stringify({
        amount: Math.round(Number(amount) * 100), // INR to Paise
        currency: "INR",
        receipt: `rcpt_${studentId}_${Date.now()}`,
      })
