const handleSupabaseError = (error: any, context: string) => {
    let message = error?.message || "Database Connection Error";
    console.error(`[Supabase Error] ${context}:`, message, error);
    throw new Error(message);
};

// --- RAZORPAY EDGE FUNCTION INTEGRATION ---

export const createRazorpayOrderApi = async (amount: number, studentId: string) => {
    const cleanAmount = Number(amount);
    try {
        console.log(`[Invoke] create-razorpay-order for Amt: ${cleanAmount}`);
        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount: cleanAmount, studentId }
        });

        if (error) {
            // "Failed to send a request" is a generic catch-all for network failure (DNS, CORS, Offline)
            console.error("[Connectivity Issue]", error);

            // If the failure is total, we offer a fallback/simulation path for testing
            return { 
                simulation: true, 
                reason: error.message || "Network request failed. Check Edge Function deployment and CORS.",
                error_type: "invoke_failed"
            };
        }

        if (!data || data.error) {
            throw new Error(data?.error || "Payment server returned an empty response.");
        }

        return data;
    } catch (err: any) {
        console.error("[createRazorpayOrderApi Exception]", err);
        return { 
            simulation: true, 
            reason: err.message || "Unknown connectivity exception.",
            error_type: "exception"
        };
    }
};

export const verifyRazorpayPaymentApi = async (orderId: string, razorpayResponse: any) => {
    if (!razorpayResponse || !razorpayResponse.razorpay_signature) {
        return false; 
    }

    try {
        const { data, error } = await supabase.functions.invoke('verify-razorpay-payment', {
            body: { 
                razorpay_order_id: razorpayResponse.razorpay_order_id,
                razorpay_payment_id: razorpayResponse.razorpay_payment_id,
                razorpay_signature: razorpayResponse.razorpay_signature
            }
        });
        if (error) {
            console.error("[Verification Invoke Failed]", error);
            return false;
        }
        return data?.success ?? false;
    } catch (err) {
        console.error("[Verification Exception]", err);
        return false; 
    }
};

