    const { data, error } = await supabase
        .from('orders')
        .select('*')
        .eq('payment_status', 'paid')
        .gte('created_at', start.toISOString())
        .lte('created_at', end.toISOString());

    if (error) return [];
    return data ? data.map(mapOrder) : [];
};

