        is_combo: !!item.isCombo, combo_items: item.combo_items || []
    };
    const { data, error } = await supabase.from('menu_items').update(dbPayload).eq('id', itemId).select().single();
    if (error) handleSupabaseError(error, "Menu Items Update");
