        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount: cleanAmount, studentId }
        });

        if (error) {
            console.error("Invoke Network Error:", error);
            // If the connection is outright rejected or function 404s, provide detailed help
            if (error.message?.includes('Failed to send a request') || error.status === 404) {
                throw new Error("Could not connect to Payment Server. Please ensure the Edge Functions are deployed in Supabase using the CLI.");
            }
            throw error;
        }

        if (!data || data.error) {
            throw new Error(data?.error || "Invalid response from Payment Server.");
        }

        return data;
    } catch (err: any) {
        console.error("createRazorpayOrderApi Exception:", err.message);
