import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import type { CartItem } from '../../types';
import { OrderStatus } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { placeOrder, createPaymentRecord, updateOrderStatus, updateOrderPaymentStatus, createRazorpayOrderApi, verifyRazorpayPaymentApi } from '../../services/mockApi';
import { CONFIG } from '../../config';

declare const Razorpay: any;

const getCartFromStorage = (): CartItem[] => {
    try {
        const cart = localStorage.getItem('cart');
        return cart ? JSON.parse(cart) : [];
    } catch {
        return [];
    }
};

const saveCartToStorage = (cart: CartItem[]) => {
    localStorage.setItem('cart', JSON.stringify(cart));
};

const CartPage: React.FC = () => {
    const [cart, setCart] = useState<CartItem[]>(getCartFromStorage());
    const [isPlacingOrder, setIsPlacingOrder] = useState(false);

    const { user, loading, promptForPhone, updateUser } = useAuth();
    const [phoneNumber, setPhoneNumber] = useState(user?.phone || '');
    const [seatNumber, setSeatNumber] = useState('');
    const [validationError, setValidationError] = useState('');

    const navigate = useNavigate();

    useEffect(() => {
        if (!loading && !user) {
            promptForPhone();
        }
    }, [user, loading, promptForPhone]);

    useEffect(() => {
        if (user && user.phone) {
            setPhoneNumber(user.phone);
        }
    }, [user]);

    const updateCart = (newCart: CartItem[]) => {
        setCart(newCart);
        saveCartToStorage(newCart);
        window.dispatchEvent(new CustomEvent('cartUpdated'));
    };

    const handleQuantityChange = (itemId: string, newQuantity: number) => {
        if (newQuantity < 1) handleRemoveItem(itemId);
        else updateCart(cart.map(item => item.id === itemId ? { ...item, quantity: newQuantity } : item));
    };

    const handleRemoveItem = (itemId: string) => updateCart(cart.filter(item => item.id !== itemId));
    const handleNotesChange = (itemId: string, notes: string) => updateCart(cart.map(item => item.id === itemId ? { ...item, notes } : item));

    const subtotal = useMemo(() => {
        return cart.reduce((sum, item) => {
            const price = Number(item.price) || 0;
            const qty = Number(item.quantity) || 0;
            return sum + (price * qty);
        }, 0);
    }, [cart]);

    const totalAmount = Number(subtotal);

    const finalizeSuccessfulOrder = async (orderId: string, paymentId: string, amount: number) => {
        try {
            await updateOrderPaymentStatus(orderId, true);
            await updateOrderStatus(orderId, OrderStatus.PENDING);
            await createPaymentRecord({
                order_id: orderId,
                student_id: user?.id,
                amount: Number(amount),
                method: 'Razorpay',
                status: 'successful',
                transaction_id: paymentId,
            });
            updateCart([]);
            navigate(`/customer/order-success/${orderId}`, { state: { showSuccessToast: true } });
        } catch (error) {
            console.error("Database Update Error:", error);
            window.dispatchEvent(new CustomEvent('show-toast', { 
                detail: { 
                    message: `Payment received but database sync failed. Order ID: ${orderId}`, 
                    type: 'payment-error' 
                } 
            }));
        } finally {
            setIsPlacingOrder(false);
        }
    };

    const handlePayment = async (orderId: string, amount: number) => {
        try {
            const rzpOrder = await createRazorpayOrderApi(amount, user!.id);

            // Handle connectivity failure or SIMULATION mode
            if (rzpOrder.simulation) {
                console.log("[Simulation] Processing payment locally...");
                // Just wait a tiny bit longer to simulate "payment processing"
                await new Promise(r => setTimeout(r, 1200));
                await finalizeSuccessfulOrder(orderId, "SIM_" + Date.now(), amount);
                return;
            }

            const options = {
                key: CONFIG.RAZORPAY_KEY_ID, 
                amount: rzpOrder.amount, 
                currency: rzpOrder.currency,
                order_id: rzpOrder.id,
                name: CONFIG.APP_NAME,
                description: "Movie Snacks Order",
                image: "/favicon.ico",
                handler: async (response: any) => {
                    setIsPlacingOrder(true);
                    const isVerified = await verifyRazorpayPaymentApi(orderId, response);
                    if (isVerified) {
                        await finalizeSuccessfulOrder(orderId, response.razorpay_payment_id, amount);
                    } else {
                        window.dispatchEvent(new CustomEvent('show-toast', { detail: { message: 'Verification failed. Contact support.', type: 'payment-error' } }));
                        setIsPlacingOrder(false);
                    }
                },
                prefill: {
                    name: user?.username || 'Customer',
                    email: user?.email || '',
                    contact: phoneNumber,
                },
                theme: { color: "#FF0033" },
                modal: {
                    ondismiss: () => {
                        setIsPlacingOrder(false);
                    }
                }
            };

            const rzp = new Razorpay(options);
            rzp.open();

        } catch (err: any) {
            // If the Edge function fails with status code, fall back to simulation automatically
            console.warn("Caught Error - Falling back to Simulator:", err.message);
            await new Promise(r => setTimeout(r, 1000));
            await finalizeSuccessfulOrder(orderId, "FAIL_BACK_SIM_" + Date.now(), amount);
        }
    };

    const handleConfirmOrder = async () => {
        if (!user) { promptForPhone(); return; }
        if (!phoneNumber.trim() || !seatNumber.trim()) { setValidationError('Delivery info required.'); return; }
        if (!/^\d{10}$/.test(phoneNumber)) { setValidationError('Invalid phone number.'); return; }

        setValidationError('');
        setIsPlacingOrder(true);

        try {
            const orderPayload = {
                studentId: user.id, 
                studentName: user.username,
                customerPhone: phoneNumber,
                items: cart.map(({ id, name, quantity, price, notes, imageUrl }) => ({ 
                    id, name, quantity: Number(quantity), price: Number(price), notes, imageUrl 
                })),
                totalAmount: Number(totalAmount),
                seat_number: seatNumber.trim(),
                status: OrderStatus.PENDING 
            };

            const order = await placeOrder(orderPayload);
            await handlePayment(order.id, Number(order.totalAmount));

        } catch (error: any) {
            console.error("Order Failure:", error);
            window.dispatchEvent(new CustomEvent('show-toast', { 
                detail: { message: "Database Error. Could not create order record.", type: 'payment-error' } 
            }));
            setIsPlacingOrder(false);
        }
    };

    if (!user) return <div className="text-center py-16 text-textPrimary"><p>Please login to continue.</p></div>;

    return (
        <div className="text-textPrimary">
            <h1 className="text-3xl font-bold font-heading mb-6">Your Cart 🛒</h1>
            {cart.length === 0 ? (
