Deno.serve(async (req) => {
  // 1. Handle CORS Preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { amount, studentId } = await req.json()

    // YOUR LIVE KEYS
    const KEY_ID = 'rzp_live_S0V6Bz1xXIWsbn'
    const KEY_SECRET = 'aleVqiBaaVo8ZatFBmWQS1vV'

    if (!amount || amount <= 0) {
      throw new Error("Invalid order amount provided.");
    }

    console.log(`[Razorpay] Creating order for Student: ${studentId}, Amount: ₹${amount}`);

    // 2. Call Razorpay API
    const auth = btoa(`${KEY_ID}:${KEY_SECRET}`)
    const response = await fetch('https://api.razorpay.com/v1/orders', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Basic ${auth}`
      },
      body: JSON.stringify({
