        receipt: `rcpt_${studentId}_${Date.now()}`,
        notes: {
          student_id: studentId,
          source: "Sangeetha Theater App"
        }
      })
    })

    const data = await response.json()

    // 3. Handle Razorpay-specific errors
    if (!response.ok) {
      console.error("Razorpay API Error Detail:", data);
      const errorMessage = data.error?.description || data.error?.reason || "Razorpay API rejected the request.";

      return new Response(
        JSON.stringify({ error: errorMessage, details: data.error }),
        { 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }, 
          status: 400 // Explicitly return 400 so the frontend catch block triggers
        }
      )
    }

    // 4. Return Success
    return new Response(
      JSON.stringify(data),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }, 
