const handleSupabaseError = (error: any, context: string) => {
    let message = error?.message || "Database Connection Error";
    console.error(`[Supabase Error] ${context}:`, message, error);
    throw new Error(message);
};

// --- REAL RAZORPAY EDGE FUNCTION INTEGRATION ---

export const createRazorpayOrderApi = async (amount: number, studentId: string) => {
    try {
        console.log(`Invoking Live Payment Function...`);

        // Use supabase.functions.invoke
        const { data, error } = await supabase.functions.invoke('create-razorpay-order', {
            body: { amount, studentId }
        });

        // Handle network errors or non-2xx status codes
        if (error) {
            console.error("Function Error Details:", error);

            // Try to extract JSON error from response if available
            if (error instanceof Error && error.message.includes('non-2xx')) {
                // If we get here, it means the server returned an error status (400, 500)
                // The actual error body might be in the data property
                throw new Error(data?.error || "Razorpay rejected the request. Please ensure the payment amount is valid.");
            }

            throw new Error(`Connection Error: ${error.message}`);
        }

        if (!data || data.error) {
            throw new Error(data?.error || "Invalid response from server.");
        }

        return data;
    } catch (err: any) {
        console.error("Razorpay Order Exception:", err.message);
        throw err;
    }
};

export const verifyRazorpayPaymentApi = async (orderId: string, razorpayResponse: any) => {
    if (!razorpayResponse || !razorpayResponse.razorpay_signature) {
        return false; 
    }

    try {
        const { data, error } = await supabase.functions.invoke('verify-razorpay-payment', {
            body: { 
                razorpay_order_id: razorpayResponse.razorpay_order_id,
                razorpay_payment_id: razorpayResponse.razorpay_payment_id,
                razorpay_signature: razorpayResponse.razorpay_signature
            }
        });

        if (error) {
            console.error("Verification connection failed:", error);
            return false;
        }

        return data?.success ?? false;
    } catch (err) {
        console.error("Verification error:", err);
        return false; 
    }
};

