                        <TabButton tab="seats" label="Seats" />
                        <TabButton tab="sales" label="Sales" icon="📊" />
                        <TabButton tab="analytics" label="Analytics" />
                        <TabButton tab="management" label="Management" />
                        <TabButton tab="history" label="History" />
