    const totalIncome = orders.reduce((sum, o) => sum + Number(o.total_amount), 0);
    const itemMap: Record<string, number> = {};

    orders.forEach(o => {
        const items = parseOrderItems(o.items);
        items.forEach(i => {
            itemMap[i.name] = (itemMap[i.name] || 0) + Number(i.quantity);
