                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-800">
                                            {salesOrders.map(order => (
                                                <tr key={order.id} className="hover:bg-gray-800/30">
                                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-mono text-gray-400">...{order.id.slice(-6)}</td>
