    return { 
        id, 
        name: userData.username, 
        phone: userData.phone, 
        totalOrders, 
        lifetimeSpend, 
        favoriteItemsCount: favoritesCount || 0, 
        loyaltyPoints: userData.loyalty_points || 0 
    };
};

